import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import clsx from 'clsx';
import './AcidDropdown.css';

export interface DropdownItem {
    id: string;
    label: string;
    icon?: React.ReactNode;
    shortcut?: string;
    onClick?: () => void;
    disabled?: boolean;
    variant?: 'default' | 'danger';
}

export interface AcidDropdownProps {
    trigger: React.ReactNode;
    items: DropdownItem[];
    align?: 'left' | 'right';
    className?: string;
}

export const AcidDropdown = ({
    trigger,
    items,
    align = 'right',
    className
}: AcidDropdownProps) => {
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    return (
        <div className={clsx('ac-dropdown-container', className)} ref={containerRef}>
            <div className="ac-dropdown-trigger" onClick={() => setIsOpen(!isOpen)}>
                {trigger}
            </div>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: -10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: -10 }}
                        transition={{ duration: 0.15, ease: [0.23, 1, 0.32, 1] }}
                        className={clsx('ac-dropdown-menu', `ac-align-${align}`)}
                    >
                        <div className="ac-dropdown-inner">
                            {items.map((item) => (
                                <button
                                    key={item.id}
                                    className={clsx(
                                        'ac-dropdown-item',
                                        item.variant === 'danger' && 'ac-item-danger',
                                        item.disabled && 'ac-item-disabled'
                                    )}
                                    disabled={item.disabled}
                                    onClick={() => {
                                        if (!item.disabled) {
                                            item.onClick?.();
                                            setIsOpen(false);
                                        }
                                    }}
                                >
                                    <div className="ac-item-left">
                                        {item.icon && <span className="ac-item-icon">{item.icon}</span>}
                                        <span className="ac-item-label">{item.label}</span>
                                    </div>
                                    {item.shortcut && <span className="ac-item-shortcut">{item.shortcut}</span>}
                                </button>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

.ac-dropdown-container {
    position: relative;
    display: inline-block;
}

.ac-dropdown-trigger {
    cursor: pointer;
}

.ac-dropdown-menu {
    position: absolute;
    top: calc(100% + 8px);
    z-index: 1000;
    min-width: 220px;
    background: var(--ac-surface);
    border: 1px solid var(--ac-border-muted);
    border-radius: var(--ac-radius-md);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
    padding: 4px;
}

.ac-align-right {
    right: 0;
}

.ac-align-left {
    left: 0;
}

.ac-dropdown-inner {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.ac-dropdown-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 8px 12px;
    border: none;
    background: transparent;
    color: var(--ac-text-secondary);
    font-family: var(--font-mono);
    font-size: 0.8rem;
    font-weight: 500;
    border-radius: var(--ac-radius-sm);
    cursor: pointer;
    transition: all 0.15s ease;
    text-align: left;
}

.ac-dropdown-item:hover:not(.ac-item-disabled) {
    background: var(--ac-surface-hover);
    color: var(--ac-text-primary);
}

.ac-item-left {
    display: flex;
    align-items: center;
    gap: 10px;
}

.ac-item-icon {
    display: flex;
    align-items: center;
    color: var(--ac-text-muted);
}

.ac-dropdown-item:hover .ac-item-icon {
    color: var(--ac-text-primary);
}

.ac-item-label {
    letter-spacing: 0.02em;
}

.ac-item-shortcut {
    font-size: 0.7rem;
    color: var(--ac-text-muted);
    letter-spacing: 0.05em;
    opacity: 0.6;
}

.ac-item-danger {
    color: var(--ac-brand);
}

.ac-item-danger:hover:not(.ac-item-disabled) {
    background: rgba(244, 67, 54, 0.1);
    color: var(--ac-brand);
}

.ac-item-disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

[data-theme='light'] .ac-dropdown-menu {
    background: white;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}
